var e=[{id:`ch1_climb`,numeral:`Chapter One`,title:`The Climb`,next:`ch2_pass`,gives:`inkStep`,flags:/^inkStep$/,line:`Mist, a bridge, and a road that only goes up.`,closing:`The rope is down. Whatever is past the gate has been waiting.`},{id:`ch2_pass`,numeral:`Chapter Two`,title:`The Broken Pass`,next:`ch3_pines`,line:`Over the mountain, where the stairs have fallen.`,closing:`From the last tooth of rock, the pines hang out over nothing.`},{id:`ch3_pines`,numeral:`Chapter Three`,title:`Hanging Pines`,next:`ch4_temple`,line:`Down the far side, on what the cliff still holds.`,closing:`Red roofs below. The bells down there have not rung in years.`},{id:`ch4_temple`,numeral:`Chapter Four`,title:`Temple of Silent Bells`,next:`ch5_sea`,gives:`sword`,flags:/^ch4_/,line:`A sword in the stone, and bells that have forgotten how.`,closing:`Every bell has spoken. Behind the temple the road goes down into black water.`},{id:`ch5_sea`,numeral:`Chapter Five`,title:`Sea of Ink`,next:`ch6_summit`,flags:/^ch5_/,line:`The tide comes in black, and it does not ask.`,closing:`The tide closes behind him. Ahead there is only snow.`},{id:`ch6_summit`,numeral:`Chapter Six`,title:`The Last Brushstroke`,next:null,flags:/^ch6_/,line:`Snow, wind, and the one who walked ahead of him.`}],t=e[0].id,n=t=>e.find(e=>e.id===t)??null;function r(t){let n={};for(let r of e){if(r.id===t)break;r.gives&&(n[r.gives]=!0)}return n}function i(e,t){let i=n(t);if(e.chapter=t,e.shrine=null,!i)return e;if(e.abilities=r(t),i.flags)for(let t of Object.keys(e.flags))i.flags.test(t)&&delete e.flags[t];return e}export{n as a,i,t as n,r,e as t};